CREATE OR REPLACE FUNCTION public.planning_terrain_references() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.planning_terrain_lire_autorise() THEN RAISE EXCEPTION 'Accès refusé' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('personnes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nom',nom,'prenom',prenom,'origine','employe','actif',actif,'poste',poste_principal,'statut',statut_contrat,'telephone',coalesce(mobile,telephone),'chef',est_chef_equipe_terrain)) FROM employes),'[]'::jsonb) || coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nom',nom,'prenom',prenom,'origine','dispos','actif',actif,'poste',poste_terrain,'statut',statut_terrain,'telephone',telephone,'chef',est_chef_equipe_terrain)) FROM dispos_intervenants WHERE employe_id IS NULL),'[]'::jsonb),'affaires',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'numero',numero,'nom',nom)) FROM affaires),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.planning_terrain_importer(_lignes jsonb,_empreinte text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; d date; a uuid; p uuid; ajoutes integer:=0; existants integer:=0; BEGIN IF NOT public.planning_terrain_ecrire_autorise() THEN RAISE EXCEPTION 'Accès refusé' USING ERRCODE='42501'; END IF; IF jsonb_typeof(_lignes)<>'array' OR jsonb_array_length(_lignes)>5000 OR _empreinte !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Import invalide'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('planning_terrain_import',0)); PERFORM set_config('app.terrain_import',auth.uid()::text,true); FOR r IN SELECT value FROM jsonb_array_elements(_lignes) LOOP IF EXISTS(SELECT 1 FROM jsonb_object_keys(r) k WHERE k NOT IN ('date','affaire_id','employe_id','operation','responsable','nom_original','sources','format')) THEN RAISE EXCEPTION 'Champ non autorisé'; END IF; d:=(r->>'date')::date; a:=(r->>'affaire_id')::uuid; p:=(r->>'employe_id')::uuid; IF d IS NULL OR d>(now() AT TIME ZONE 'Europe/Paris')::date OR NOT EXISTS(SELECT 1 FROM affaires WHERE id=a) OR NOT EXISTS(SELECT 1 FROM employes WHERE id=p) THEN RAISE EXCEPTION 'Date, personne ou chantier invalide'; END IF; IF EXISTS(SELECT 1 FROM assignations WHERE affaire_id=a AND employe_id=p AND date=d) THEN existants:=existants+1; CONTINUE; END IF; INSERT INTO assignations(affaire_id,employe_id,date,demi_journee,heures,terrain,historique_terrain,validation_logistique,source_terrain,type_operation,created_by,provenance_terrain) VALUES(a,p,d,'JOURNEE',0,true,true,'valide','historique_consolide',nullif(r->>'operation',''),auth.uid(),jsonb_build_object('empreinte',_empreinte,'nom_original',left(r->>'nom_original',200),'sources',left(r->>'sources',2000),'format',left(r->>'format',100),'responsable',left(r->>'responsable',200))); ajoutes:=ajoutes+1; END LOOP; RETURN jsonb_build_object('ajoutes',ajoutes,'existants',existants); END $$;
CREATE OR REPLACE FUNCTION public.planning_terrain_historique_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN IF OLD.historique_terrain AND NOT public.planning_terrain_ecrire_autorise() THEN RAISE EXCEPTION 'Accès refusé'; END IF; RETURN OLD; END IF; IF TG_OP='UPDATE' AND OLD.terrain AND NOT NEW.terrain THEN RAISE EXCEPTION 'Périmètre terrain immuable'; END IF; IF NEW.historique_terrain THEN IF NOT NEW.terrain OR NOT public.planning_terrain_ecrire_autorise() OR current_setting('app.terrain_import',true) IS DISTINCT FROM auth.uid()::text THEN RAISE EXCEPTION 'Historique réservé à l’import validé'; END IF; IF NEW.heures<>0 OR NEW.date>(now() AT TIME ZONE 'Europe/Paris')::date OR NEW.etape_logistique_id IS NOT NULL OR NEW.heure_debut IS NOT NULL OR NEW.heure_fin IS NOT NULL THEN RAISE EXCEPTION 'Durée historique inconnue'; END IF; NEW.statut_confirmation:='non_requise'; NEW.est_chef_jour:=false; END IF; RETURN NEW; END $$;
CREATE TRIGGER terrain_historique_guard BEFORE INSERT OR UPDATE OR DELETE ON public.assignations FOR EACH ROW EXECUTE FUNCTION public.planning_terrain_historique_guard();
DROP TRIGGER trg_check_affaire_open_assignation ON public.assignations;
CREATE TRIGGER trg_check_affaire_open_assignation BEFORE INSERT OR UPDATE ON public.assignations FOR EACH ROW WHEN(NOT NEW.historique_terrain) EXECUTE FUNCTION public.check_affaire_open_for_assignation();
DROP TRIGGER trg_set_confirmation ON public.assignations;
CREATE TRIGGER trg_set_confirmation BEFORE INSERT OR UPDATE ON public.assignations FOR EACH ROW WHEN(NOT NEW.historique_terrain) EXECUTE FUNCTION public.set_assignation_confirmation_status();
DROP TRIGGER trg_notify_assignation_change ON public.assignations;
CREATE TRIGGER trg_notify_assignation_change_write AFTER INSERT OR UPDATE ON public.assignations FOR EACH ROW WHEN(NOT NEW.terrain) EXECUTE FUNCTION public.notify_assignation_change();
CREATE TRIGGER trg_notify_assignation_change_delete AFTER DELETE ON public.assignations FOR EACH ROW WHEN(NOT OLD.terrain) EXECUTE FUNCTION public.notify_assignation_change();
DROP TRIGGER trg_notify_confirmation ON public.assignations;
CREATE TRIGGER trg_notify_confirmation AFTER INSERT OR UPDATE OF statut_confirmation ON public.assignations FOR EACH ROW WHEN(NOT NEW.terrain) EXECUTE FUNCTION public.notify_assignation_confirmation();
DROP TRIGGER trg_aeh_assignations ON public.assignations;
CREATE TRIGGER trg_aeh_assignations_write AFTER INSERT OR UPDATE ON public.assignations FOR EACH ROW WHEN(NOT NEW.historique_terrain) EXECUTE FUNCTION public.trg_aeh_on_assignation();
CREATE TRIGGER trg_aeh_assignations_delete AFTER DELETE ON public.assignations FOR EACH ROW WHEN(NOT OLD.historique_terrain) EXECUTE FUNCTION public.trg_aeh_on_assignation();
REVOKE ALL ON FUNCTION public.planning_terrain_references(),public.planning_terrain_importer(jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.planning_terrain_references(),public.planning_terrain_importer(jsonb,text) TO authenticated;